const joinEs = (a) => (a.length <= 1 ? a.join('') : a.slice(0, -1).join(', ') + ' y ' + a[a.length - 1]);
const joinEn = (a) => (a.length <= 1 ? a.join('') : a.slice(0, -1).join(', ') + ' and ' + a[a.length - 1]);
const listOf = (v, T, join) => (v.list ? join(v.list.split(',').filter(Boolean).map((k) => T.opt[k] || k)) : '');
/** Loop diuretic dose in the chosen drug's own units (furosemide 40 mg ≈ bumetanide 1 mg ≈ torasemide 20 mg ≈ ethacrynic acid 50 mg). */
const loopMg = (drug, eq) => ({ furosemide: eq, bumetanide: eq / 40, torasemide: eq / 2, ethacrynic: eq * 1.25 }[drug]);
const fmtN = (x) => (Math.round(x * 10) / 10).toString();

