      ev: { start: 'Terlipressin + albumin.', contraindicated: 'Hypoxaemia or overload: risk of respiratory failure.', reversal: 'Hepatorenal syndrome reversed.', noResponse: 'No response at 3 days: consider alternatives.', respiratoryFailure: 'Respiratory failure.', dialysis: 'Creatinine > 4: consider dialysis.' },
