      s: { tkv: 'Total kidney volume', egfr: 'GFR', uVol: 'Urine output' },
      st: { camp: 'ADH → V2 → cAMP in cyst cells.', cysts: 'Cysts grow and GFR falls.', v2Block: 'Tolvaptan blocks V2.', lessCamp: 'Less cAMP: cysts grow more slowly.', aquaresis: 'Aquaresis: large volumes of dilute urine.' },
      ev: { start: 'Tolvaptan.', liverMonitoring: 'Monthly transaminases for the first 18 months.', aquaresis: 'Polyuria > 4 L/day.', egfr25: 'GFR < 25 mL/min.' },
      dec: { considerRisk: 'Mayo 1C: weigh the risk of progression.', indicated: 'Rapid progression: tolvaptan indicated.' },
      ref: ['Kidney growth ≈ 2.8 vs 5.5%/year with and without tolvaptan.'],
