      ev: { start: (v, T) => `Pillars: ${listOf(v, T, joinEn) || 'none indicated'}.`, notIndicated: (v, T) => `${T.opt[v.pillar]}: not indicated in this disease.`, kidneyFailure: (v) => `Kidney failure (GFR < 15) at year ${v.y}.`, albuminuriaDown: 'Albuminuria −30%.' },
      dec: { dkdT2: 'Type 2 diabetes: ACE inhibitor/ARB + SGLT2 inhibitor + finerenone + semaglutide.', dkdT1: 'Type 1 diabetes: ACE inhibitor/ARB + finerenone (SGLT2 inhibitors and GLP-1 RAs not indicated).', igan: 'IgA: ACE inhibitor/ARB + SGLT2 inhibitor + endothelin antagonist.', fsgs: 'FSGS: ACE inhibitor/ARB + SGLT2 inhibitor; sparsentan without nephrotic syndrome.', nondiabetic: 'Non-diabetic CKD: ACE inhibitor/ARB + SGLT2 inhibitor.' },
