      ev: { start: (v, T) => `${T.opt[v.alkali]}.`, target: 'Bicarbonate ≥ 22 mmol/L.', hyperK: 'Hyperkalaemia.', hypoK: 'Hypokalaemia.', sodiumLoad: 'Sodium load > 100 mmol/day: watch oedema and blood pressure.' },
      dec: { ckd: 'CKD: bicarbonate if HCO₃⁻ < 18 mmol/L.', distalRta: 'Distal tubular acidosis: potassium citrate.' },
