      ev: { start: (v, T) => `${T.opt[v.deficit]}: ${v.route === 'iv' ? 'IV' : 'oral'} repletion.`, refractoryK: 'Refractory hypokalaemia: magnesium is missing.', repleted: 'Deficit replaced.', diarrhoea: 'Oral magnesium: diarrhoea limits the dose.', kNormal: 'Potassium ≥ 3.5 mmol/L.', ivPhosphateRisk: 'IV phosphate: watch calcium and kidney function.' },
