      s: { urate: 'Serum urate', flare: 'Flare risk' },
      g: { target: 'Urate (target < 6)' },
      st: { production: 'The liver produces urate (xanthine oxidase).', excretion: 'The kidney excretes it (URAT1 reabsorbs it).', xo: 'Xanthine oxidase is inhibited.', uricase: 'Uricase converts urate to allantoin.', urat1: 'URAT1 is inhibited: more urate in urine.', dissolve: 'Urate < 6: crystals dissolve.' },
      ev: { start: (v, T) => `${T.opt[v.drug]}.`, hlaRisk: 'HLA-B*58:01: risk of severe hypersensitivity to allopurinol.', startLow: 'Allopurinol: start low and titrate.', cvWarning: 'Febuxostat: caution in cardiovascular disease.', ineffectiveGfr: 'Probenecid poorly effective at this GFR.', liver: 'Benzbromarone: monitor liver function.', g6pd: 'Pegloticase: exclude G6PD deficiency.', target6: 'Urate < 6 mg/dL.', target5: 'Urate < 5 mg/dL.', flare: 'Gout flare as urate falls without prophylaxis.' },
