      ev: { start: (v, T) => `${T.opt[v.drug]}.`, hemolysis: 'G6PD deficiency: rasburicase causes haemolysis; contraindicated.', highUrate: 'Urate > 12 mg/dL.', urateLow: 'Urate < 4 mg/dL.', aki: 'Acute urate nephropathy.' },
